pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 10 ether);
        // adversarial log: a log that rejects AddMessage
        RevertingLog log = new RevertingLog();
        c.SetLogFile(address(log));
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        if (amount > 0) {
            try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        } else {
            try c.Deposit() { ok = true; } catch { ok = false; }
        }
        // Rule: once the log is configured to a log that rejects AddMessage,
        // a Deposit through c must revert (c routes messages through the
        // configured log). The mutant replaces the log with address(0), whose
        // empty account silently accepts the call, so its Deposit succeeds.
        assertTrue(!ok);
    }
}

contract RevertingLog {
    function AddMessage(address, uint, string calldata) external pure {
        revert("log rejects");
    }
}

